def add(todos: list[Todo], title: str) -> list[Todo]:
    next_id = max((t.id for t in todos), default=0) + 1
    return [*todos, Todo(next_id, title)]

def complete(todos: list[Todo], todo_id: int) -> list[Todo]:
    if not any(t.id == todo_id for t in todos):
        raise KeyError(f"no todo with id {todo_id}")
    return [Todo(t.id, t.title, True) if t.id == todo_id else t for t in todos]

def render(todos: list[Todo]) -> str:
    return "\n".join(f"[{'x' if t.done else ' '}] {t.id}. {t.title}" for t in todos)
